/*
 * The ready-made interface: banner, preferences, reopen button and placeholders, in plain DOM.
 * Same structure and accessibility as the components generated by `zeste add`.
 */
import { ACTION_ATTRIBUTE, auditBanner, auditReopen, reportIssues, whenSettled, type ConsentManager } from '@zeste/core';
import type { Messages } from '@zeste/services/i18n';

export interface UiOptions {
  manager: ConsentManager;
  messages: Messages;
  style: 'zeste' | 'pelure';
  theme: 'site' | 'system' | 'light' | 'dark';
  privacyUrl?: string;
  showIcon: boolean;
  guard: boolean;
}

export interface Ui {
  open(): void;
  close(): void;
}

type Attrs = Record<string, string | boolean | undefined>;

function h(tag: string, attrs: Attrs = {}, ...children: Array<Node | string | false | undefined>): HTMLElement {
  const el = document.createElement(tag);
  for (const [name, value] of Object.entries(attrs)) {
    if (value === true) el.setAttribute(name, '');
    else if (typeof value === 'string') el.setAttribute(name, value);
  }
  for (const child of children) if (child) el.append(child);
  return el;
}

/** Citrus wedge, drawn with the skin colors. */
function wedge(size = 26): SVGElement {
  const template = document.createElement('template');
  template.innerHTML = `<svg class="zeste-wedge" width="${size}" height="${size}" viewBox="0 0 26 26" aria-hidden="true"><circle cx="13" cy="13" r="12" style="fill:var(--zeste-accent,#f5d742);stroke:var(--zeste-ink)" stroke-width="1.5"/><g style="stroke:var(--zeste-ink)" stroke-width="1.2"><line x1="13" y1="3" x2="13" y2="23"/><line x1="3" y1="13" x2="23" y2="13"/><line x1="6" y1="6" x2="20" y2="20"/><line x1="20" y1="6" x2="6" y2="20"/></g><circle cx="13" cy="13" r="2.2" style="fill:var(--zeste-paper)"/></svg>`;
  return template.content.firstElementChild as SVGElement;
}

/** HTML of the placeholder shown in place of a blocked embed (`<div class="youtube_player">`…). */
export function placeholderHtml(skin: Pick<UiOptions, 'style' | 'theme'>) {
  return (service: { key: string; name: string }, messages: { allow: string; fallback: string }): string => {
    const box = h('div', { class: 'zeste-placeholder', 'data-zeste-skin': skin.style, 'data-zeste-theme': skin.theme, 'data-zeste-service': service.key });
    box.append(
      h(
        'div',
        {},
        h('p', {}, `${service.name} ${messages.fallback}`),
        h('button', { type: 'button', class: 'zeste-btn', 'data-zeste-allow': service.key }, `${messages.allow} ${service.name}`),
      ),
    );
    return box.outerHTML;
  };
}

export function mountUi(options: UiOptions): Ui {
  const { manager, messages: t, style, theme } = options;
  const skin = { 'data-zeste-skin': style, 'data-zeste-theme': theme };
  const action = (name: 'acceptAll' | 'denyAll' | 'openPreferences' | 'savePreferences', label: string, className = 'zeste-btn') =>
    h('button', { type: 'button', class: className, [ACTION_ATTRIBUTE]: name }, label);

  // ---------- Banner ----------
  const text = h('p', { class: 'zeste-text' }, t.alertBigPrivacy);
  if (options.privacyUrl) text.append(' ', h('a', { href: options.privacyUrl }, t.privacyUrl));
  const deny = action('denyAll', t.denyAll);
  const accept = action('acceptAll', t.acceptAll);
  const customize = action('openPreferences', t.personalize, 'zeste-link');
  const banner = h(
    'section',
    { class: 'zeste-banner', 'aria-label': t.icon, 'data-zeste-banner': true, hidden: true, ...skin },
    h('div', { class: 'zeste-intro' }, h('span', { class: 'zeste-title' }, wedge(), t.icon), text),
    h('div', { class: 'zeste-actions' }, deny, accept, customize),
  );
  deny.addEventListener('click', () => manager.denyAll());
  accept.addEventListener('click', () => manager.grantAll());
  customize.addEventListener('click', () => open());

  // ---------- Reload notice and reopen button ----------
  const reloadButton = h('button', { type: 'button', class: 'zeste-btn' }, t.reload);
  reloadButton.addEventListener('click', () => location.reload());
  const reload = h('div', { class: 'zeste-reload', role: 'status', hidden: true, ...skin }, reloadButton);
  const icon = h('button', { type: 'button', class: 'zeste-icon', 'aria-label': t.alertSmall, [ACTION_ATTRIBUTE]: 'openPreferences', hidden: true, ...skin }, wedge(24));
  icon.addEventListener('click', () => open());

  // ---------- Preferences ----------
  const draft = new Map<string, boolean>();
  const body = h('div', { style: 'display:contents' });
  const prefs = h(
    'dialog',
    { class: 'zeste-prefs', 'aria-labelledby': 'zeste-prefs-title', ...skin },
    h('h2', { id: 'zeste-prefs-title' }, t.title),
    h('p', { class: 'zeste-desc' }, t.disclaimer),
    body,
  ) as HTMLDialogElement;
  const prefsDeny = action('denyAll', t.denyAll);
  const prefsAccept = action('acceptAll', t.acceptAll);
  const save = action('savePreferences', t.save, 'zeste-btn zeste-save');
  const closeButton = h('button', { type: 'button', class: 'zeste-close', 'aria-label': t.close }, h('span', { 'aria-hidden': 'true' }, '✕'));
  prefs.append(h('div', { class: 'zeste-actions' }, prefsDeny, prefsAccept, save), closeButton);
  prefsDeny.addEventListener('click', () => {
    manager.denyAll();
    close();
  });
  prefsAccept.addEventListener('click', () => {
    manager.grantAll();
    close();
  });
  save.addEventListener('click', () => {
    manager.set(Object.fromEntries(draft));
    close();
  });
  closeButton.addEventListener('click', () => close());

  function renderPreferences() {
    const { services } = manager.getSnapshot();
    const categories = new Map<string, typeof services[number][]>();
    for (const service of services) {
      if (service.needsConsent) categories.set(service.category, [...(categories.get(service.category) ?? []), service]);
    }
    body.replaceChildren(
      ...[...categories].map(([key, list]) => {
        const label = t.categories[key];
        return h(
          'section',
          { class: 'zeste-category', 'aria-labelledby': `zeste-category-${key}` },
          h('h3', { id: `zeste-category-${key}` }, label?.title ?? key),
          label?.details ? h('p', {}, label.details) : undefined,
          h(
            'ul',
            {},
            ...list.map((service) => {
              const id = `zeste-service-${service.key}`;
              const toggle = h('button', { type: 'button', role: 'switch', id, class: 'zeste-switch', 'aria-checked': String(draft.get(service.key)) }, h('span'));
              toggle.addEventListener('click', () => {
                const next = !draft.get(service.key);
                draft.set(service.key, next);
                toggle.setAttribute('aria-checked', String(next));
              });
              const privacy =
                service.privacyUrl &&
                h(
                  'a',
                  { href: service.privacyUrl, target: '_blank', rel: 'noreferrer' },
                  t.privacyUrl,
                  ' ',
                  h('span', { class: 'zeste-sr-only' }, `${service.name} ${t.newWindow}`),
                );
              return h('li', {}, h('div', {}, h('label', { for: id }, service.name), privacy), toggle);
            }),
          ),
        );
      }),
    );
    const exempt = services.filter((s) => !s.needsConsent);
    if (exempt.length) {
      body.append(h('p', { class: 'zeste-exempt' }, h('strong', {}, t.mandatoryTitle), ` : ${exempt.map((s) => s.name).join(', ')}`));
    }
  }

  /** Opens the preferences with the current choices (undecided = refused: nothing pre-checked). */
  function open() {
    draft.clear();
    for (const s of manager.getSnapshot().services) if (s.needsConsent) draft.set(s.key, s.status === 'granted');
    renderPreferences();
    if (!prefs.open) prefs.showModal();
  }

  function close() {
    if (prefs.open) prefs.close();
  }

  document.body.append(reload, banner, icon, prefs);

  let audited = false;
  manager.subscribe((snapshot) => {
    banner.hidden = snapshot.decided;
    icon.hidden = !snapshot.decided || !options.showIcon;
    reload.hidden = !snapshot.needsReload;
    if (!options.guard) return;
    if (!snapshot.decided && !audited) {
      audited = true;
      requestAnimationFrame(() => requestAnimationFrame(async () => {
        await whenSettled(banner);
        if (banner.isConnected && !banner.hidden) reportIssues(auditBanner(banner));
      }));
    }
    if (snapshot.decided) setTimeout(() => reportIssues(auditReopen()), 1000);
  });

  return { open, close };
}
